import build as b
from build import t,label,url,link,img,video,toggle,eyebrow,actions,cta,steps,faqs

def crumb(key):return f'<div class="wrap breadcrumbs">{link("home")} &nbsp; / &nbsp; {label(key)}</div>'
def field(name,fr,en,kind='text',required=False,options=None,full=False):
 lab=t(fr,en);rid=f'{name}-error';req=' required' if required else '';common=f'id="{name}" name="{name}" aria-describedby="{rid}"{req}'
 if options:control=f'<select {common}>'+''.join(f'<option value="{v}">{t(a,c)}</option>' for v,a,c in options)+'</select>'
 elif kind=='textarea':control=f'<textarea {common} rows="4" maxlength="4000"></textarea>'
 else:control=f'<input {common} type="{kind}"'+(' min="0"' if kind=='number' else '')+(' autocomplete="name"' if name=='nom' else ' autocomplete="email"' if kind=='email' else ' autocomplete="tel"' if kind=='tel' else '')+'>'
 return f'<div class="field {"full" if full else ""}"><label for="{name}">{lab}<span data-required>{" *" if required else ""}</span></label>{control}<span class="field-error" id="{rid}"></span></div>'
def notice():return f'<div class="notice">{t("Les demandes en ligne seront bientôt disponibles. Pour organiser votre déménagement dès maintenant, appelez le","Online requests will be available soon. To arrange your move now, call")} <a href="tel:+33171361838">01 71 36 18 38</a>.</div>'
def privacy():return f'<p class="fine-print">{t("Vos informations servent uniquement à étudier votre projet et à vous recontacter. Aucun envoi n’est effectué tant que le service en ligne n’est pas activé.","Your information is used only to assess your move and contact you. Nothing is sent until the online service is activated.")} {link("privacy",t("En savoir plus","Read more"))}</p><div class="honeypot" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div>'
def contact_fields():return field('nom','Nom complet','Full name',required=True)+field('preference','Contact préféré','Preferred contact',options=[('telephone','Téléphone','Phone'),('email','E-mail','Email')])+field('telephone','Téléphone','Phone',kind='tel')+field('email','Adresse e-mail','Email address',kind='email')
def contact():return crumb('contact')+f'''<section class="section" style="padding-top:30px"><div class="wrap contact-grid"><div>{eyebrow('Faisons connaissance','Let’s talk')}<h1 style="font-size:clamp(3rem,5vw,5.2rem)">{t('Parlons de votre<br><em>déménagement.</em>','Let’s talk about<br><em>your move.</em>')}</h1><p class="lead">{t('Quelques informations suffisent pour commencer à préparer votre projet.','A few details are all we need to start planning your move.')}</p><div class="contact-details"><span class="eyebrow">{t('Un échange direct','Speak to us directly')}</span><a href="tel:+33171361838">01 71 36 18 38</a><a href="tel:+33667570912">06 67 57 09 12</a><p class="inset">39 boulevard de Strasbourg<br>94130 Nogent-sur-Marne</p><p class="subtle">{t('À votre service à Paris, en Île-de-France, en France et en Europe.','Serving Paris, Greater Paris, France and Europe.')}</p></div></div><form class="form-box" id="contact-form" novalidate><h2 style="font-size:2.4rem">{t('Votre projet commence ici.','Your move starts here.')}</h2>{notice()}<div class="fields">{contact_fields()}{field('projet','Type de projet','Project type',options=[('particulier','Particulier','Home move'),('entreprise','Entreprise','Business move'),('rappel','Demande de rappel','Callback request'),('autre','Autre besoin','Other enquiry')])}{field('periode','Période souhaitée','Preferred dates')}{field('depart','Ville de départ','Moving from')}{field('arrivee','Ville d’arrivée','Moving to')}{field('message','Votre message','Your message',kind='textarea',full=True)}</div>{privacy()}<button class="btn" type="submit">{t('Envoyer ma demande','Send my enquiry')}</button><p class="form-status" role="status" aria-live="polite"></p></form></div></section>'''
def quote():
 choices=[('emballage','Emballage','Packing'),('deballage','Déballage','Unpacking'),('demontage','Démontage','Dismantling'),('remontage','Remontage','Reassembly'),('stockage','Garde-meubles','Storage'),('monte','Monte-meubles','Furniture lift'),('fragile','Objets fragiles ou spécialisés','Fragile or specialist items')]
 opts=''.join(f'<label class="option"><input type="checkbox" name="prestations" value="{t(a,c)}" '+(f'data-reveal="details-{v}"' if v in ['stockage','fragile'] else '')+f'>{t(a,c)}</label>' for v,a,c in choices)
 unsure=[('inconnu','Je ne sais pas','I don’t know'),('oui','Oui','Yes'),('non','Non','No')]
 accesses=''
 for side,fr,en in [('depart','Au départ','At collection'),('arrivee','À l’arrivée','At delivery')]:
  accesses+=f'<fieldset><legend>{t(fr,en)}</legend><div class="fields">'+field(side+'-lieu','Type de lieu','Property type',options=[('inconnu','Je ne sais pas','I don’t know'),('appartement','Appartement','Flat'),('maison','Maison','House'),('bureaux','Bureaux / locaux','Office / business premises'),('autre','Autre','Other')])+field(side+'-etage','Étage (ou « Je ne sais pas »)','Floor (or “I don’t know”)')+field(side+'-ascenseur','Ascenseur disponible ?','Lift available?',options=unsure)+field(side+'-parking','Stationnement possible ?','Parking available?',options=unsure)+field(side+'-acces','Précisions sur les accès','Access details',kind='textarea')+'</div></fieldset>'
 return crumb('devis')+f'''<section><div class="wrap quote-layout"><aside class="quote-aside">{eyebrow('Votre projet, simplement','Your move, made simple')}<h1>{t('Un nouveau départ.<br><em>Préparons-le ensemble.</em>','A new beginning.<br><em>Let’s plan it together.</em>')}</h1><p>{t('Quelques étapes pour comprendre votre besoin. Vous pouvez revenir en arrière à tout moment.','A few steps to understand your needs. You can go back at any time.')}</p><ol class="steps-nav"><li class="active">{t('Le projet','Your move')}</li><li>{t('Les accès','Access')}</li><li>{t('Les prestations','Services')}</li><li>{t('Vos coordonnées','Your details')}</li></ol><a class="text-link" href="tel:+33171361838">{t('Besoin d’aide ? 01 71 36 18 38','Need help? +33 1 71 36 18 38')}</a></aside><form class="form-box" id="quote-form" novalidate><p class="eyebrow" data-step-counter></p><div class="progress-track"><div class="progress-bar"></div></div><section class="step"><h2 tabindex="-1">{t('Parlez-nous de votre projet.','Tell us about your move.')}</h2><p class="subtle">{t('Commençons par le trajet et vos besoins.','Let’s start with your route and needs.')}</p><div class="fields">{field('profil','Vous êtes','You are',options=[('particulier','Un particulier','A private individual'),('entreprise','Une entreprise','A business')])}{field('service','Service principal','Main service',options=[('demenagement','Déménagement','Moving'),('stockage','Garde-meubles','Storage'),('monte','Monte-meubles','Furniture lift'),('objets','Objets spécialisés','Specialist items')])}{field('depart','Ville / code postal de départ','Collection town / postcode',required=True)}{field('arrivee','Ville / code postal d’arrivée','Delivery town / postcode')}{field('periode','Date ou période souhaitée','Preferred date or period')}{field('flexibilite','Vos dates sont-elles flexibles ?','Are your dates flexible?',options=[('oui','Oui','Yes'),('non','Non','No'),('inconnu','À préciser','To be confirmed')])}</div></section><section class="step" hidden><h2 tabindex="-1">{t('Les lieux et leurs accès.','Your properties and access.')}</h2><p class="subtle">{t('Pas besoin de tout connaître. Indiquez « Je ne sais pas » si nécessaire.','You don’t need every detail. Enter “I don’t know” where needed.')}</p><div class="fields">{field('surface','Surface approximative (m² ou « Je ne sais pas »)','Approximate area (m² or “I don’t know”)')}{field('volume','Volume estimé (m³ ou « Je ne sais pas »)','Estimated volume (m³ or “I don’t know”)')}</div><div class="access-grid inset">{accesses}</div></section><section class="step" hidden><h2 tabindex="-1">{t('Que souhaitez-vous nous confier ?','What would you like us to handle?')}</h2><p>{t('Sélectionnez les prestations à étudier. Leur périmètre sera précisé dans le devis.','Select the services to discuss. Their scope will be confirmed in your quote.')}</p><fieldset><legend>{t('Les prestations souhaitées','Requested services')}</legend><div class="options">{opts}</div></fieldset><div id="details-stockage" hidden>{field('duree-stockage','Durée de stockage envisagée','Expected storage duration')}</div><div id="details-fragile" hidden>{field('objets-details','Quels objets nécessitent une attention particulière ?','Which items need special attention?',kind='textarea')}</div><p class="fine-print">{t('Le monte-meubles et la manutention spécialisée sont soumis à l’étude des accès.','Furniture lifts and specialist handling are subject to an access assessment.')}</p></section><section class="step" hidden><h2 tabindex="-1">{t('Restons en contact.','Let’s stay in touch.')}</h2><div class="fields">{contact_fields()}{field('message','Une précision pour votre projet ?','Anything else we should know?',kind='textarea',full=True)}</div><div class="review"><h3 class="inset">{t('Votre récapitulatif','Your summary')}</h3><dl class="review-values"></dl><div class="actions"><button type="button" data-edit-step="0">{t('Modifier le projet','Edit your move')}</button><button type="button" data-edit-step="1">{t('Modifier les accès','Edit access')}</button><button type="button" data-edit-step="2">{t('Modifier les prestations','Edit services')}</button></div></div>{notice()}{privacy()}</section><div class="form-actions"><button class="btn outline" type="button" data-prev hidden>{t('Précédent','Back')}</button><button class="btn" type="button" data-next>{t('Continuer','Continue')}</button><button class="btn" type="submit" data-submit hidden>{t('Envoyer ma demande','Send my enquiry')}</button></div><p class="form-status" role="status" aria-live="polite"></p></form></div></section>'''

if __name__=='__main__':
 for lang in ['fr','en']:
  b.LANG=lang;b.write('contact',contact());b.write('devis',quote())
